<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Rfq,Contact,ReplacementRequest,User};use Illuminate\Http\Request;
class InquiryController extends Controller {public function rfqs(){return view('admin.rfqs.index',['rfqs'=>Rfq::with('assignee')->latest()->paginate(30)]);}public function rfqShow(Rfq $rfq){$rfq->load(['items.product','attachments','assignee']);return view('admin.rfqs.show',['rfq'=>$rfq,'salesUsers'=>User::whereIn('role',['super_admin','administrator','sales'])->where('is_active',1)->get()]);}public function rfqUpdate(Request $r,Rfq $rfq){$d=$r->validate(['status'=>'required|in:new,reviewed,assigned,contacted,quotation_sent,negotiation,won,lost,closed','priority'=>'required|in:low,normal,high,urgent','assigned_to'=>'nullable|exists:users,id','notes'=>'nullable|max:10000']);$rfq->update($d);return back()->with('success','RFQ updated.');}public function contacts(){return view('admin.contacts.index',['contacts'=>Contact::latest()->paginate(30)]);}public function replacements(){return view('admin.replacements.index',['items'=>ReplacementRequest::latest()->paginate(30)]);}public function replacementUpdate(Request $r,ReplacementRequest $replacement){$replacement->update($r->validate(['status'=>'required|in:new,reviewing,matched,quoted,closed']));return back()->with('success','Status updated.');}}
